<script setup lang="ts">import{onMounted,ref}from'vue';import DefaultLayout from '@/layouts/DefaultLayout.vue';import{useApi}from'@/composables/useApi';import type{ApiResponse,Certificate}from'@/types';const api=useApi(),items=ref<Certificate[]>([]);async function load(){const r=await api.get<ApiResponse<Certificate[]>>('/certificates/me');items.value=r.data||[]}onMounted(load)</script>
<template><DefaultLayout><main class="mx-auto max-w-5xl px-4 py-10"><h1 class="mb-7 text-3xl font-extrabold">Chứng chỉ của tôi</h1><div class="grid gap-5 md:grid-cols-2"><article v-for="c in items" :key="c.id" class="rounded-3xl border-2 border-purple-100 bg-white p-7 dark:border-purple-900 dark:bg-slate-900"><div class="text-4xl">🎓</div><p class="mt-4 text-sm font-bold uppercase tracking-widest text-purple-600">Certificate of completion</p><h2 class="mt-2 text-2xl font-extrabold">{{ c.courseTitleSnapshot }}</h2><p class="mt-2">Cấp cho <b>{{ c.studentNameSnapshot }}</b></p><p class="text-sm text-slate-500">Giảng viên: {{ c.instructorNameSnapshot }}</p><p class="mt-4 font-mono text-sm">{{ c.certificateNumber }}</p><RouterLink :to="`/certificates/verify/${c.verificationCode}`" class="mt-5 inline-block font-bold text-purple-600">Xác minh công khai →</RouterLink></article><p v-if="!items.length" class="text-slate-500">Bạn chưa có chứng chỉ.</p></div></main></DefaultLayout></template>
